/**
 * Igualar el cuadro de cada contorno no alcanza: un tigre es largo y bajo y un
 * perro es alto, así que a igual caja el perro pesa el doble. Se los lleva a la
 * misma ALTURA (50 de 100) —lo que se percibe como "mismo tamaño" cuando van
 * uno al lado del otro—, con el ancho como techo para los muy alargados, que
 * quedan un poco más bajos antes que recortados.
 */
const FIT: Record<string, string> = {
  "Rata": "translate(1.03 1.06) scale(0.979)",
  "Buey": "translate(5.71 5.70) scale(0.886)",
  "Tigre": "translate(1.00 1.03) scale(0.979)",
  "Gato": "translate(22.71 23.46) scale(0.546)",
  "Serpiente": "translate(11.06 11.05) scale(0.779)",
  "Caballo": "translate(3.06 3.06) scale(0.939)",
  "Cabra": "translate(19.65 19.64) scale(0.607)",
  "Mono": "translate(12.26 12.26) scale(0.755)",
  "Gallo": "translate(21.77 21.76) scale(0.565)",
  "Perro": "translate(15.29 15.26) scale(0.694)",
  "Cerdo": "translate(2.45 2.46) scale(0.940)",
  "Dragón": "translate(15.47 19.58) scale(0.691)",
};

export default function ZodiacAnimalIcon({
  animal,
  size = 24,
  className = "",
  title,
}: ZodiacAnimalIconProps) {
  const canonical = normalizeZodiacAnimal(animal);
  const label = title || canonical || animal;
  const paths = SILHOUETTES[canonical];

  return (
    <svg
      viewBox="0 0 100 100"
      width={size}
      height={size}
      className={`inline-block shrink-0 align-middle ${className}`}
      role="img"
      aria-label={label}
    >
      {paths ? (
        <g fill="currentColor" transform={FIT[canonical]}>
          {paths.map((d, i) => (
            <path key={i} d={d} />
          ))}
        </g>
      ) : (
        <g fill="none" stroke="currentColor" strokeLinecap="round">
          <circle cx="50" cy="50" r="26" strokeWidth="2.4" opacity="0.35" />
          <circle cx="50" cy="50" r="8" fill="currentColor" stroke="none" opacity="0.3" />
        </g>
      )}
    </svg>
  );
}
